from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(19,'proportionnalite','La proportionnalité en actes','5 · Modéliser et organiser',
'Fois plus · Fois moins · Ajouter des situations',
['Reconnaître une situation de proportionnalité et la justifier.','Raisonner par « fois plus », « fois moins » et par addition de situations.','Résoudre des problèmes en plusieurs étapes.'],
['Proportionnalité du CM1, multiplication et division.'],[
page(1,'Reconnaître, toujours justifier',
bloc('definition',r'Deux grandeurs sont en situation de proportionnalité quand multiplier l’une par un nombre multiplie l’autre par le même nombre : 3 fois plus de baguettes, 3 fois plus cher ; 4 fois moins de feuilles, pile 4 fois moins épaisse.'),
bloc('exemple',r'Le prix de cahiers identiques est proportionnel à leur nombre. Contre-exemples : la taille selon l’âge, un forfait avec part fixe, un tarif dégressif. La phrase « fois plus » doit être vraie pour tous les nombres, pas seulement une fois.'),
bloc('attention',r'Au cours moyen, le raisonnement s’écrit en français : « Si j’achète 3 fois plus, je paie 3 fois plus. » Ni tableau de proportionnalité, ni produit en croix : les phrases suffisent et montrent le sens.'),
bloc('savoirfaire',r'Contrôler la vraisemblance : plus de croissants doit coûter plus cher, moins de temps doit donner moins d’eau. Un résultat qui varie à contresens signale une erreur de raisonnement.','Le bon sens d’abord')),
page(2,'Combiner les situations',
bloc('savoirfaire',r'Quand 4 stylos coûtent 6 euros et 2 stylos coûtent 3 euros, alors $4+2=6$ stylos coûtent $6+3=9$ euros : deux situations s’additionnent. Avec « fois plus » et « addition », presque tous les nombres deviennent accessibles.','Additionner deux situations'),
bloc('exemple',r'Prix de 10 m de ruban connaissant 4 m à 6 euros : 2 m coûtent 3 euros (2 fois moins), et $10=4+4+2$ : $6+6+3=15$ euros. On enchaîne « fois moins » puis sommes.'),
bloc('propriete',r'Les recettes, les débits réguliers, les prix au mètre ou au kilogramme se traitent ainsi. La donnée de départ sert de brique : on la double, la triple, la partage, puis on assemble.'),
bloc('attention',r'La fraction aide aussi : 6 crêpes utilisent 150 g de farine, donc 1 crêpe environ 25 g ? Oui, mais seulement si la situation est proportionnelle : toujours le vérifier avant de calculer.'))
],[
E('Proportionnel ou pas ?',r'Dire si la situation relève de la proportionnalité : le prix de baguettes identiques ; l’âge et la pointure ; la distance parcourue à allure régulière selon la durée.',r'Baguettes : $\res{\text{oui}}$. Âge et pointure : $\res{\text{non}}$, doubler l’âge ne double pas la pointure. Allure régulière : $\res{\text{oui}}$, 2 fois plus de temps, 2 fois plus de distance.','Tester la phrase « fois plus » sur chaque situation.','assert 2*2==4'),
E('Fois plus',r'Quatre croissants coûtent 5 euros. Combien coûtent 12 croissants ?',r'12 croissants, 3 fois plus : $5\times3=\res{15}$ euros.','Chercher le lien multiplicatif entre 4 et 12.','assert 12//4==3 and 5*3==15'),
E('Fois moins',r'Six litres de peinture couvrent 30 m². Quelle surface couvrent 2 litres ? Et 18 litres ?',r'2 L, 3 fois moins : $30:3=\res{10}$ m². 18 L, 3 fois plus : $30\times3=\res{90}$ m².','Relier chaque quantité à la donnée de départ.','assert 30//3==10 and 30*3==90'),
E('Additionner deux situations',r'Quatre stylos coûtent 6 euros. Combien coûtent 2 stylos ? En déduire le prix de 6 stylos.',r'2 stylos, 2 fois moins : $\res3$ euros. Et $6=4+2$ stylos : $6+3=\res9$ euros.','Assembler les deux achats connus.','assert 6//2==3 and 6+3==9'),
E('La recette au départ',r'Pour 6 crêpes, il faut 150 g de farine. Quelle masse pour 18 crêpes ? Pour 9 crêpes ?',r'18 crêpes : 3 fois plus, $150\times3=\res{450}$ g. 9 crêpes $=6+3$ : $150+75=\res{225}$ g, avec 3 crêpes à 75 g (2 fois moins que 6).','Combiner « fois plus », « fois moins » et sommes.','assert 150*3==450 and 150//2==75 and 150+75==225'),
E('Le débit de la pompe',r'Une pompe régulière remplit 80 L en 4 minutes.'+Q(r'Quel volume en 12 minutes ?',r'En combien de temps remplit-elle 200 L ?'),r'12 min, 3 fois plus : $80\times3=\res{240}$ L. Pour 200 L : $200=80+80+40$, soit $4+4+2=\res{10}$ min, avec 40 L en 2 min (2 fois moins).','Découper 200 L en briques de 80 et 40.','assert 80*3==240 and 80+80+40==200 and 4+4+2==10'),
E('Le prix au kilogramme',r'Trois kilogrammes de pommes coûtent $5{,}40$ euros. Combien coûte 1 kg ? Et 7 kg ?',r'1 kg, 3 fois moins : $5{,}40:3=\res{1{,}80}$ euro. 7 kg : $7\times1{,}80=\res{12{,}60}$ euros ; ou $6$ kg $+1$ kg $=10{,}80+1{,}80$.','Revenir à l’unité quand elle simplifie tout.','assert Rational("5.40")/3==Rational("1.80") and 7*Rational("1.80")==Rational("12.60")'),
E('L’échelle du plan',r'Sur un plan, 1 cm représente 50 m réels. Quelle distance réelle pour 7 cm sur le plan ? Et quelle longueur sur le plan pour 350 m réels ?',r'7 cm : $50\times7=\res{350}$ m. Réciproquement, 350 m, c’est 7 fois 50 m : $\res7$ cm sur le plan.','Compter les paquets de 50 mètres.','assert 50*7==350 and 350//50==7'),
E('Le piège du forfait',r'Un escalade-parc coûte 8 euros d’entrée puis 2 euros par activité. Léo dit : « 6 activités coûtent deux fois plus cher que 3 activités. » Vérifier et conclure.',r'3 activités : $8+6=14$ euros ; 6 activités : $8+12=20$ euros. Or $14\times2=28\ne20$ : $\res{\text{non proportionnel}}$, la part fixe casse le « fois plus ».','Calculer les deux montants complets.','assert 8+3*2==14 and 8+6*2==20 and 20!=28'),
E('Les deux imprimantes',r'L’imprimante A sort 120 pages en 3 minutes ; la B, 150 pages en 4 minutes, toutes deux à allure régulière. Laquelle est la plus rapide ? Justifier en comparant sur 12 minutes.',r'En 12 min : A, 4 fois plus, imprime $120\times4=480$ pages ; B, 3 fois plus, $150\times3=450$ pages. $\res{\text{A est la plus rapide}}$.','Comparer sur une même durée multiple commune.','assert 120*4==480 and 150*3==450 and 480>450'),
E('La course régulière',r'Un cycliste roule à allure régulière : 24 km en 1 heure. Quelle distance en 2 h 30 ?',r'2 h : $24\times2=48$ km ; 30 min, 2 fois moins qu’une heure : 12 km. Total : $48+12=\res{60}$ km.','Découper la durée en briques simples.','assert 24*2==48 and 24//2==12 and 48+12==60'),
E('Les photocopies de l’école',r'Cent photocopies coûtent 4 euros. Combien coûtent 250 photocopies ?',r'$250=100+100+50$ : $4+4+2=\res{10}$ euros, avec 50 copies à 2 euros (2 fois moins que 100).','Assembler des paquets de 100 et de 50.','assert 4+4+2==10 and 100+100+50==250'),
E('La maquette',r'Une maquette réduit toutes les longueurs de la même façon : la voiture réelle de 4 m est représentée par 8 cm. Quelle longueur sur la maquette pour un bus de 12 m ? Et pour un vélo de 2 m ?',r'12 m, 3 fois plus que 4 m : $8\times3=\res{24}$ cm. 2 m, 2 fois moins : $8:2=\res4$ cm. La réduction uniforme est une proportionnalité.','Multiplier les longueurs par le même facteur.','assert 8*3==24 and 8//2==4'),
E('Comparer les lots',r'Le lot A offre 5 cahiers pour 7 euros ; le lot B, 10 cahiers pour $13{,}50$ euros. Quel lot est le plus avantageux ?',r'Deux lots A donnent 10 cahiers pour $7\times2=14$ euros, contre $13{,}50$ euros en B : $\res{\text{B est plus avantageux}}$ de $0{,}50$ euro.','Ramener les deux offres au même nombre de cahiers.','assert 7*2==14 and Rational("13.50")<14 and 14-Rational("13.50")==Rational(".50")'),
E('Proportionnel, le périmètre ?',r'Quand on triple le côté d’un carré, son périmètre triple-t-il ? Et son aire ? Tester avec un côté de 2 cm, puis conclure.',r'Périmètres : $4\times2=8$ et $4\times6=24=8\times3$ : le périmètre $\res{\text{triple}}$, il est proportionnel au côté. Aires : $4$ et $36=4\times9$ : l’aire est multipliée par $\res9$ : non proportionnelle au côté.','Tester chaque grandeur séparément.','assert 4*2==8 and 4*6==24 and 24==3*8 and 2*2==4 and 6*6==36 and 36==9*4')
],reperes=['Reconnaître et justifier','Fois plus, fois moins','Additionner des situations','Comparaisons et échelles'],deco='courbe')

chapitre(20,'donnees','Lire et croiser des données','5 · Modéliser et organiser',
'Tableaux · Barres · Courbes · Diagrammes circulaires',
['Lire tableaux, diagrammes en barres, courbes et diagrammes circulaires.','Construire un tableau ou un diagramme à partir de données.','Croiser plusieurs documents pour répondre à une question.'],
['Lectures de graphiques du CM1.'],[
page(1,'Des tableaux aux diagrammes',
bloc('definition',r'Un tableau à double entrée se lit au croisement d’une ligne et d’une colonne. Un diagramme en barres porte un effectif par barre, lu sur l’axe gradué. Les totaux contrôlent l’ensemble : la somme des effectifs retrouve le nombre de réponses.'),
bloc('exemple',r'Les données réelles, souvent liées au climat ou à la biodiversité, s’annoncent avec leurs unités : millimètres de pluie, degrés Celsius, nombre d’espèces. Les lire, c’est d’abord lire le titre et les axes.'),
bloc('savoirfaire',r'Avant toute lecture : repérer le pas des graduations. Un carreau peut valoir 2, 5, 10 ou 100 : le même dessin raconte alors d’autres nombres.','Le pas des graduations'),
bloc('attention',r'Entre deux points mesurés, une courbe relie sans garantir : les valeurs intermédiaires sont des estimations, pas des mesures.')),
page(2,'Le diagramme circulaire',
bloc('definition',r'Un diagramme circulaire partage un disque proportionnellement aux effectifs : la moitié du disque représente la moitié du total, un quart en représente le quart. On le lit en comparant les secteurs au disque entier.'),
r'@FIG:cours-circulaire@',
bloc('savoirfaire',r'Lire un circulaire : identifier le total, puis traduire chaque secteur en fraction simple du disque : moitié, quart, tiers. Un secteur d’un quart sur 60 réponses représente $60:4=15$ réponses.','Du secteur à l’effectif'),
bloc('attention',r'Le circulaire montre des parts du tout, pas une évolution : pour suivre une grandeur dans le temps, la courbe reste l’outil adapté. Choisir le graphique selon la question posée.'))
],[
E('Le tableau de l’enquête',r'L’enquête « sport préféré » donne :'+tableau(['Sport','foot','danse','judo','natation'],[['Effectif','12','9','5','4']])+r'Combien d’élèves ont répondu ? Quel sport arrive en tête ?',r'Total : $12+9+5+4=\res{30}$ élèves. Le $\res{\text{foot}}$ arrive en tête avec 12 voix.','Contrôler le total avant de conclure.','assert 12+9+5+4==30 and max([12,9,5,4])==12'),
E('Double entrée',r'Le tableau croise deux classes et deux sorties.'+tableau(['','Musée','Forêt'],[['CM2 A','15','11'],['CM2 B','9','17']])+r'Combien d’élèves de CM2 B préfèrent la forêt ? Combien d’élèves préfèrent le musée ?',r'Croisement CM2 B-forêt : $\res{17}$. Colonne musée : $15+9=\res{24}$ élèves.','Croiser la ligne et la colonne demandées.','assert 17==17 and 15+9==24'),
E('Lire les barres',r'Le diagramme donne les livres empruntés chaque jour ; une graduation vaut 5. Lire les valeurs de lundi et de jeudi, et dire quel jour bat le record.',r'Lundi : $\res{15}$ ; jeudi : $\res{35}$, la barre la plus haute : record le $\res{\text{jeudi}}$.','Multiplier les graduations par leur pas.','assert 35>15',figure='don-3'),
E('La courbe de l’année',r'La courbe donne la température moyenne de chaque mois. Quel est le mois le plus froid ? Quel est l’écart entre juillet et janvier ?',r'Le point le plus bas est en $\res{\text{janvier}}$ ($3\,^\circ$C) ; juillet culmine à $23\,^\circ$C : écart $23-3=\res{20}$ degrés.','Chercher les points extrêmes.','assert 23-3==20',figure='don-4'),
E('Le circulaire de la cantine',r'Le diagramme circulaire montre les choix de 60 élèves : la moitié a choisi le plat A, un quart le plat B, le reste le plat C. Donner les trois effectifs.',r'A : $60:2=\res{30}$ ; B : $60:4=\res{15}$ ; C : le reste, $60-30-15=\res{15}$ élèves.','Traduire chaque secteur en fraction du total.','assert 60//2==30 and 60//4==15 and 60-30-15==15',figure='don-5'),
E('Construire le diagramme',r'Construire le diagramme en barres des sports de l’exercice 1, avec une graduation de 2.',r'Quatre barres de hauteurs 12, 9, 5 et 4 : le dessin figure en vert, chaque hauteur lue sur l’axe gradué de 2 en 2.','Une barre par sport, hauteur égale à l’effectif.','assert max([12,9,5,4])==12',figure='don-6'),
E('Compléter le tableau',r'Compléter les cases manquantes :'+tableau(['','Lundi','Mardi','Total'],[['Entrées','145','?','313'],['Goûters','?','96','184']])+r'',r'Mardi-entrées : $313-145=\res{168}$. Lundi-goûters : $184-96=\res{88}$. Les totaux pilotent les cases manquantes.','Utiliser chaque total de ligne.','assert 313-145==168 and 184-96==88'),
E('Les points du repère',r'Chaque point donne la taille d’un plant de tomate selon la semaine. Lire la taille en semaine 2 et en semaine 5, puis dire entre quelles semaines la croissance a été la plus forte.',r'Semaine 2 : $\res{14}$ cm ; semaine 5 : $\res{38}$ cm. Le plus grand bond sépare les semaines $\res{3\text{ et }4}$ : de 18 à 30 cm, soit 12 cm.','Comparer les écarts entre points voisins.','assert 38>14 and 30-18==12',figure='don-8'),
E('Vrai ou faux sur le circulaire',r'Sur un circulaire, le secteur « vélo » couvre un quart du disque. Peut-on dire que 25 élèves viennent à vélo ? Justifier.',r'$\res{\text{Non}}$ sans connaître le total : un quart de 60 fait 15, un quart de 100 fait 25. Un secteur donne une part du tout, pas un effectif tout seul.','Chercher le total avant de convertir.','assert 60//4==15 and 100//4==25'),
E('Deux documents à croiser',r'Le tableau donne les ventes du matin : 48 pains ; la courbe indique 76 pains vendus sur la journée. Combien de pains ont été vendus l’après-midi ?',r'$76-48=\res{28}$ pains l’après-midi. Croiser deux documents, c’est soustraire ou additionner leurs informations.','Prendre une donnée dans chaque document.','assert 76-48==28',figure='don-10'),
E('La barre incohérente',r'Le tableau annonce : CP 22, CE1 26, CE2 24. Une barre du diagramme contredit le tableau : laquelle ? Corriger.',r'La barre $\res{\text{CE1}}$ monte à 22 au lieu de $\res{26}$ ; la correction figure en vert. Toujours confronter graphique et données sources.','Comparer chaque barre à sa valeur.','assert 26!=22',figure='don-11'),
E('L’enquête à construire',r'Réponses brutes à « Combien de livres as-tu lus ce mois-ci ? » : 0, 1, 2, 1, 0, 3, 1, 2, 1, 0, 2, 1.'+Q(r'Construire le tableau des effectifs.',r'Combien d’élèves ont lu au moins 2 livres ?'),r'Effectifs : 0 livre : $\res3$ ; 1 livre : $\res5$ ; 2 livres : $\res3$ ; 3 livres : $\res1$. Total 12 réponses. Au moins 2 livres : $3+1=\res4$ élèves.','Compter en barrant les réponses une à une.','assert 3+5+3+1==12 and 3+1==4'),
E('Le climat en deux graphiques',r'Pour une même ville, la courbe donne les températures mensuelles et le diagramme en barres les précipitations. Quel mois cumule chaleur maximale et pluie minimale ?',r'La courbe culmine en $\res{\text{juillet}}$ ($23\,^\circ$C) et la barre de juillet est la plus basse (18 mm) : juillet cumule les deux records. Croiser les deux documents répond à la question.','Lire chaque document puis croiser.','assert 23==23 and 18==18',figure='don-13'),
E('Choisir le bon graphique',r'Pour chaque question, choisir l’outil adapté — tableau, courbe ou circulaire : suivre la taille d’une plante semaine après semaine ; montrer la part de chaque sport dans la classe ; retrouver une valeur exacte parmi cinquante relevés.',r'L’évolution : la $\res{\text{courbe}}$. Les parts du tout : le $\res{\text{circulaire}}$. La valeur exacte : le $\res{\text{tableau}}$. Chaque question a son graphique.','Associer question et point fort de chaque outil.','assert 1==1'),
E('Le piège de la lecture rapide',r'Un diagramme en barres sur les ventes commence ses graduations à 50, et la barre B semble deux fois plus haute que la barre A. A : 60 ventes, B : 70 ventes. Expliquer l’illusion.',r'L’axe tronqué ne montre que ce qui dépasse 50 : les hauteurs dessinées (10 contre 20) doublent, mais les ventes réelles passent seulement de 60 à $\res{70}$. Lire les valeurs, pas l’impression visuelle.','Vérifier l’origine de l’axe avant de comparer.','assert 70-60==10 and 70!=2*60')
],reperes=['Tableaux et totaux','Barres et courbes','Diagrammes circulaires','Croiser et critiquer'],deco='statistiques')

chapitre(21,'probabilites','Les probabilités : a chances sur b','5 · Modéliser et organiser',
'Issues · Équiprobabilité · Arbres et tableaux',
['Exprimer une probabilité sous la forme « a chances sur b ».','Comparer des probabilités en dénombrant les issues.','Recenser les issues d’une expérience à deux étapes.'],
['Vocabulaire du hasard et fractions.'],[
page(1,'Quantifier les chances',
bloc('definition',r'Quand toutes les issues d’une expérience ont les mêmes chances — dé équilibré, boules indiscernables, cartes bien mélangées —, la situation est équiprobable. La probabilité d’un évènement s’exprime alors par « a chances sur b » : a issues favorables parmi b issues en tout.'),
bloc('exemple',r'Obtenir un nombre pair avec un dé : les issues 2, 4, 6 parmi 6, soit 3 chances sur 6 — autant de chances de réussir que d’échouer. Tirer un cœur dans un jeu de 32 cartes : 8 chances sur 32.'),
bloc('savoirfaire',r'Comparer deux évènements : compter leurs issues favorables sur le même total. « Plus grand que 4 » (issues 5 et 6) et « au plus 2 » (issues 1 et 2) ont exactement les mêmes chances : 2 sur 6. Le décompte tranche, pas l’intuition.','Compter avant de comparer'),
bloc('attention',r'Le dé ne se souvient de rien : après trois 6 de suite, le quatrième lancer garde 1 chance sur 6 de donner un 6. Chaque répétition de l’expérience repart à neuf : c’est l’indépendance des lancers.')),
page(2,'Recenser sans rien oublier',
bloc('definition',r'Pour une expérience en deux étapes — deux lancers, deux tirages —, un tableau à double entrée ou un arbre recense toutes les issues : chaque case ou chaque chemin est une issue.'),
r'@FIG:cours-arbre@',
bloc('exemple',r'Deux pièces lancées : les issues sont PP, PF, FP, FF, quatre chemins équiprobables. « Obtenir exactement un pile » est réalisé par PF et FP : 2 chances sur 4, une chance sur deux.'),
bloc('savoirfaire',r'Construire l’arbre étape par étape : les branches de la première étape, puis, au bout de chacune, les branches de la seconde. Le nombre total d’issues est le produit des possibilités : $2\times2=4$ pour deux pièces, $6\times6=36$ pour deux dés.','L’arbre, étage par étage'),
bloc('attention',r'PF et FP sont deux issues différentes : la première pièce et la seconde jouent chacune leur rôle. Les confondre fausse tous les comptes.'))
],[
E('Premières fractions de chances',r'Avec un dé équilibré, donner les chances : d’obtenir 6 ; d’obtenir un nombre pair ; d’obtenir un nombre de 1 à 6.',r'Obtenir 6 : $\res{1\ \text{chance sur }6}$. Pair : 3 issues, $\res{3\ \text{chances sur }6}$. De 1 à 6 : toutes les issues, $\res{6\ \text{chances sur }6}$ : certain.','Compter les issues favorables sur le total.','assert Rational(1,6)<Rational(3,6)<Rational(6,6)'),
E('Le sac de boules',r'Un sac contient 2 boules rouges, 3 vertes et 5 noires, indiscernables au toucher. Donner les chances de tirer chaque couleur.',r'Rouge : $\res{2\ \text{chances sur }10}$ ; verte : $\res{3\ \text{sur }10}$ ; noire : $\res{5\ \text{sur }10}$, une chance sur deux.','Prendre les 10 boules comme issues.','assert 2+3+5==10 and Rational(5,10)==Rational(1,2)',figure='pro-2'),
E('Le jeu de 32 cartes',r'Dans un jeu de 32 cartes bien mélangé, donner les chances de tirer : un cœur ; une carte rouge ; l’as de pique.',r'Cœur : $\res{8\ \text{chances sur }32}$. Rouge : $\res{16\ \text{sur }32}$, une chance sur deux. L’as de pique : $\res{1\ \text{sur }32}$.','Compter les cartes favorables.','assert Rational(8,32)==Rational(1,4) and Rational(16,32)==Rational(1,2)'),
E('Équiprobable ou pas ?',r'La roue A a 8 secteurs identiques ; la roue B a un grand secteur et trois petits. Sur quelle roue peut-on parler de « 1 chance sur 8 » pour chaque secteur ? Pourquoi ?',r'Sur la roue $\res A$ : ses 8 secteurs identiques ont les mêmes chances. Sur B, le grand secteur sort plus souvent : les issues ne sont pas équiprobables, le compte « 1 sur 4 » serait faux.','Vérifier l’égalité des secteurs avant de compter.','assert 8==8',figure='pro-4'),
E('Comparer deux évènements',r'Avec un dé, quel évènement est le plus probable : « obtenir plus grand que 4 » ou « obtenir au plus 2 » ? Justifier.',r'Plus grand que 4 : issues 5 et 6, soit 2 chances sur 6. Au plus 2 : issues 1 et 2, encore $\res{2\ \text{chances sur }6}$ : $\res{\text{égalité}}$ parfaite, contre l’intuition.','Lister les issues favorables des deux côtés.','assert len([a for a in range(1,7) if a>4])==2 and len([a for a in range(1,7) if a<=2])==2'),
E('La mémoire du dé',r'Jade a obtenu trois 6 de suite. Elle affirme : « Le 6 a moins de chances de sortir au prochain lancer, il est fatigué ! » Corriger.',r'Le dé $\res{\text{ne se souvient pas}}$ : chaque lancer est une nouvelle expérience, le 6 garde $\res{1\ \text{chance sur }6}$. Les lancers précédents n’influencent pas le suivant.','Revenir à l’indépendance des lancers.','assert Rational(1,6)==Rational(1,6)'),
E('Les deux pièces',r'On lance deux pièces. Lister toutes les issues dans un arbre, puis donner les chances d’obtenir exactement un pile.',r'Issues : PP, PF, FP, FF — quatre chemins équiprobables. Exactement un pile : PF et FP, soit $\res{2\ \text{chances sur }4}$, une chance sur deux.','Distinguer PF et FP.','assert 2*2==4 and Rational(2,4)==Rational(1,2)',figure='pro-7'),
E('Le tableau des deux dés',r'On lance deux dés et on fait la somme. Combien y a-t-il d’issues en tout ? Combien donnent une somme de 7 ?',r'Le tableau $6\times6$ recense $\res{36}$ issues. La somme 7 sort par (1 ; 6), (2 ; 5), (3 ; 4), (4 ; 3), (5 ; 2), (6 ; 1) : $\res{6\ \text{chances sur }36}$.','Compter les cases du tableau.','assert 6*6==36 and len([(a,b) for a in range(1,7) for b in range(1,7) if a+b==7])==6',figure='pro-8'),
E('Pile puis dé',r'On lance une pièce puis un dé. Combien d’issues compte l’expérience ? Donner les chances d’obtenir « face puis un 6 ».',r'$2\times6=\res{12}$ issues équiprobables. « Face puis 6 » est un seul chemin : $\res{1\ \text{chance sur }12}$.','Multiplier les possibilités des deux étapes.','assert 2*6==12'),
E('Plus probable que son contraire ?',r'Dans un sac, 7 jetons gagnants et 3 perdants. L’évènement « tirer un gagnant » est-il plus probable que son contraire ? Donner les deux comptes de chances.',r'Gagnant : $\res{7\ \text{chances sur }10}$ ; perdant : $\res{3\ \text{sur }10}$. Le gagnant dépasse la chance sur deux : $\res{\text{oui}}$, il est plus probable que son contraire.','Comparer à la moitié du total.','assert Rational(7,10)>Rational(1,2)>Rational(3,10)'),
E('Les deux tirages de jetons',r'Un sac contient un jeton rouge et un bleu. On tire un jeton, on le remet, on retire. Lister les issues, puis donner les chances d’obtenir deux couleurs différentes.',r'Issues : RR, RB, BR, BB — quatre chemins. Couleurs différentes : RB et BR, $\res{2\ \text{chances sur }4}$, une chance sur deux.','Remettre le jeton rend les étapes identiques.','assert Rational(2,4)==Rational(1,2)',figure='pro-11'),
E('La loterie honnête ?',r'Une tombola vend 200 billets dont 8 gagnants. Maé dit : « J’ai 8 chances sur 200, c’est moins d’une chance sur 20. » A-t-elle raison ?',r'$8$ sur $200$ se compare à $10$ sur $200$ (une chance sur 20) : $8<10$, donc $\res{\text{oui}}$, moins d’une chance sur 20. Les fractions de chances se comparent comme les fractions.','Écrire « une chance sur 20 » sur le même total.','assert Rational(8,200)<Rational(1,20)==Rational(10,200)'),
E('Construire l’expérience',r'Inventer une expérience équiprobable où « gagner » a exactement 3 chances sur 8, puis la décrire.',r'Par exemple : une roue à $\res8$ secteurs identiques dont $\res3$ marqués « gagné » ; ou un sac de 8 boules indiscernables dont 3 rouges. L’essentiel : 8 issues de mêmes chances, 3 favorables.','Choisir 8 issues équiprobables dont 3 favorables.','assert Rational(3,8)<Rational(1,2)'),
E('Le détour par le contraire',r'Avec un dé, donner les chances de « ne pas obtenir 6 », puis expliquer le lien avec les chances d’« obtenir 6 ».',r'Ne pas obtenir 6 : les issues 1 à 5, $\res{5\ \text{chances sur }6}$. Avec « obtenir 6 » (1 sur 6), les deux comptes réunissent les $\res6$ issues : un évènement et son contraire se partagent toutes les issues.','Compter ce qui reste quand l’évènement échoue.','assert Rational(5,6)+Rational(1,6)==1'),
E('Le grand tri',r'On tire une carte d’un jeu de 32. Classer du moins probable au plus probable : « tirer l’as de cœur », « tirer un as », « tirer un cœur », « tirer une carte rouge ou noire ».',r'1 sur 32, puis 4 sur 32, puis 8 sur 32, puis 32 sur 32 : $\res{\text{as de cœur}<\text{as}<\text{cœur}<\text{certain}}$. Le dernier évènement est réalisé par toutes les issues.','Compter les cartes favorables de chacun.','assert Rational(1,32)<Rational(4,32)<Rational(8,32)<1')
],reperes=['a chances sur b','Comparer par les issues','Indépendance des répétitions','Arbres et tableaux à deux étapes'],deco='probabilites')
